const items = $input.all();

let resultado = [];

for (const item of items) {
  let raw = item.json.data;

  if (!raw) continue;

  let parsed;

  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      throw new Error('Erro ao fazer parse: ' + raw.substring(0, 100));
    }
  } else {
    parsed = raw;
  }

  const lista = parsed?.dataset?.itemAutF || [];

  // 🔥 aqui muda a estrutura (cabeçalho)
  resultado.push({
    numero_pedido: item.json.numero_pedido,
    cod_filial: item.json.filial,
    itens: lista // array completo dentro
  });
}

return resultado.map(item => ({
  json: item
}));

const items = $input.all();

let resultado = [];

for (const item of items) {
  const data = item.json;

  const raw =
    data.dados ??
    data.data ??
    data.body ??
    data.response ??
    data;

  let parsed;

  if (typeof raw === 'string') {
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      throw new Error('Erro ao fazer parse: ' + raw.substring(0, 200));
    }
  } else {
    parsed = raw;
  }

  const lista =
    parsed?.dataset?.autoForne ??
    parsed?.autoForne ??
    parsed?.dataset ??
    [];

  if (Array.isArray(lista)) {
    resultado.push(
      ...lista.map(i => ({
        json: i
      }))
    );
  } else {
    resultado.push({ json: parsed });
  }
}

return resultado;

const item = $input.first().json;

// tenta achar o campo automaticamente
const raw =
  item.dados ??
  item.data ??
  item.body ??
  item.response ??
  item;

// tenta converter só se for string
let parsed;

if (typeof raw === 'string') {
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error('Erro ao fazer parse: ' + raw.substring(0, 200));
  }
} else {
  parsed = raw;
}

// tenta encontrar o array correto
const lista =
  parsed?.dataset?.autoForne ??
  parsed?.autoForne ??
  parsed?.dataset ??
  [];

// garante que é array
if (!Array.isArray(lista)) {
  return [{ json: parsed }];
}

// explode em itens
return lista.map(i => ({
  json: i
}));
